    'bmc.confirmPower': 'Envoyer « {action} » à {host} ?',
    'bmc.credsHint': 'Compatible iLO 4/5, iDRAC 9 et tout BMC parlant le Redfish standard. Les identifiants ne sont jamais stockés sur le serveur ; ils restent dans cette page le temps de la session.',
    'bmc.discover': 'Découvrir',
    'bmc.discoverTip': 'Interroger ces BMC en Redfish et lister ce qu’ils exposent',
    'bmc.discovering': 'Interrogation des BMC…',
    'bmc.discovery': 'Découverte des BMC',
    'bmc.disks': 'disque(s)',
    'bmc.dispatched': 'Action lancée :',
    'bmc.f.device': 'Disque d’installation',
    'bmc.f.dns': 'DNS',
    'bmc.f.ntp': 'NTP',
    'bmc.f.advYaml': 'YAML avancé',
